Opening javascript:(function(){
  setTool('rectangle');
  const cv = document.getElementById('c');
  const r = cv.getBoundingClientRect();

  function fire(type, x, y) {
    const evt = new PointerEvent(type, {
      clientX: r.left + x,
      clientY: r.top + y,
      bubbles: true,
      pointerId: 1
    });
    cv.dispatchEvent(evt);
  }

  // Draw rectangle at (100, 100) to (400, 300)
  fire('pointerdown', 100, 100);
  fire('pointermove', 400, 300);
  fire('pointerup', 400, 300);

  // Switch to ellipse
  setTool('ellipse');

  // Draw circle (ellipse) completely inside rectangle: (150, 130) to (350, 270)
  fire('pointerdown', 150, 130);
  fire('pointermove', 350, 270);
  fire('pointerup', 350, 270);
})();
